# Pagination helper for Spotify lists
def fetch_all(api_func, access_token):
    results = []
    page_index = 0
    while True:
        page = api_func(access_token=access_token, page_index=page_index)
        if not page:
            break
        results.extend(page)
        page_index += 1
    return results

# Compute artist IDs from liked songs
liked = fetch_all(apis.spotify.show_liked_songs, token)
liked_artist_ids = set()
for song in liked:
    for artist in song.artists:
        liked_artist_ids.add(artist.id)

# Follow all liked artists not already followed
following = fetch_all(apis.spotify.show_following_artists, token)
following_ids = {a.artist_id for a in following}
for artist_id in liked_artist_ids:
    if artist_id not in following_ids:
        apis.spotify.follow_artist(access_token=token, artist_id=artist_id)
